-- توسيمُ مواضعِ الاقتباسات القرآنية في `qa_questions` (الحقلان المعروضان:
-- `evidence` و`answer`). وُلِّد آليًّا بـ scripts/locate-quran-quotes.py:
-- كلُّ موضعٍ هنا مقابَلٌ بنصّ المصحف المحلّي (public/data/quran) ووحيدٌ فيه،
-- ولم يُوسَم ما تعدَّد موضعُه (AMBIGUOUS) ولا ما لم يوجد (NOT_FOUND).
-- النصُّ كاملٌ لكلِّ صفّ ⇒ إعادةُ التشغيل لا تُغيِّر شيئًا.
BEGIN;
-- (١) الحقل evidence — ١٩ صفًّا
UPDATE qa_questions SET evidence = 'لكلِّ قصّةٍ ممّا ذُكر موضعُها: آدمُ وخروجُه من الجنّة ﴿فَأَزَلَّهُمَا ٱلشَّيْطَٰنُ عَنْهَا فَأَخْرَجَهُمَا مِمَّا كَانَا فِيهِ﴾ [البقرة: ٣٦]؛ ونوحٌ وسفينتُه ﴿وَٱصْنَعِ ٱلْفُلْكَ بِأَعْيُنِنَا وَوَحْيِنَا﴾ [هود: ٣٧]؛ وإبراهيمُ عند البيت — والمنصوصُ **رفعُ القواعد مع إسماعيلَ** لا ابتداءُ البناء وحدَه: ﴿وَإِذْ يَرْفَعُ إِبْرَٰهِۦمُ ٱلْقَوَاعِدَ مِنَ ٱلْبَيْتِ وَإِسْمَٰعِيلُ﴾ [البقرة: ١٢٧]؛ ويوسفُ وإخوتُه ﴿فَلَمَّا ذَهَبُوا۟ بِهِۦ وَأَجْمَعُوٓا۟ أَن يَجْعَلُوهُ فِى غَيَٰبَتِ ٱلْجُبِّ﴾ [يوسف: ١٥]؛ وموسى وفرعونُ ﴿فَأَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ أَنِ ٱضْرِب بِّعَصَاكَ ٱلْبَحْرَ ۖ فَٱنفَلَقَ﴾ [الشعراء: ٦٣]؛ وعيسى وولادتُه ﴿قَالَتْ أَنَّىٰ يَكُونُ لِى غُلَٰمٌۭ وَلَمْ يَمْسَسْنِى بَشَرٌۭ وَلَمْ أَكُ بَغِيًّۭا﴾ [مريم: ٢٠] ﴿قَالَ كَذَٰلِكِ قَالَ رَبُّكِ هُوَ عَلَىَّ هَيِّنٌۭ﴾ [مريم: ٢٠-٢١]؛ ويونسُ والحوتُ ﴿فَٱلْتَقَمَهُ ٱلْحُوتُ وَهُوَ مُلِيمٌۭ﴾ [الصافات: ١٤٢] ﴿فَلَوْلَآ أَنَّهُۥ كَانَ مِنَ ٱلْمُسَبِّحِينَ﴾ [الصافات: ١٤٣] ﴿لَلَبِثَ فِى بَطْنِهِۦٓ إِلَىٰ يَوْمِ يُبْعَثُونَ﴾ [الصافات: ١٤٢-١٤٤]، ودعاؤُه ﴿فَنَادَىٰ فِى ٱلظُّلُمَٰتِ أَن لَّآ إِلَٰهَ إِلَّآ أَنتَ سُبْحَٰنَكَ إِنِّى كُنتُ مِنَ ٱلظَّٰلِمِينَ﴾ [الأنبياء: ٨٧] ﴿فَٱسْتَجَبْنَا لَهُۥ وَنَجَّيْنَٰهُ مِنَ ٱلْغَمِّ﴾ [الأنبياء: ٨٧-٨٨].'
  WHERE id = '060849ce-80ac-4fde-93aa-ad8647ad2cc0';
UPDATE qa_questions SET evidence = 'نصُّ التكليف: ﴿ٱذْهَبْ إِلَىٰ فِرْعَوْنَ إِنَّهُۥ طَغَىٰ﴾ [طه: ٢٤]. ودعوى فرعونَ الألوهيةَ منصوصةٌ في موضعين: ﴿فَقَالَ أَنَا۠ رَبُّكُمُ ٱلْأَعْلَىٰ﴾ [النازعات: ٢٤]، و﴿وَقَالَ فِرْعَوْنُ يَٰٓأَيُّهَا ٱلْمَلَأُ مَا عَلِمْتُ لَكُم مِّنْ إِلَٰهٍ غَيْرِى﴾ [القصص: ٣٨]، واستكبارُه ومَن معه: ﴿وَٱسْتَكْبَرَ هُوَ وَجُنُودُهُۥ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ﴾ [القصص: ٣٩]. والآيتانِ اللتان أُيِّد بهما موسى: ﴿قَالَ أَلْقِهَا يَٰمُوسَىٰ﴾ [طه: ١٩] ﴿فَأَلْقَىٰهَا فَإِذَا هِىَ حَيَّةٌۭ تَسْعَىٰ﴾ [طه: ١٩-٢٠]، و﴿وَٱضْمُمْ يَدَكَ إِلَىٰ جَنَاحِكَ تَخْرُجْ بَيْضَآءَ مِنْ غَيْرِ سُوٓءٍ ءَايَةً أُخْرَىٰ﴾ [طه: ٢٢]. وفَلْقُ البحر ثم النجاةُ والإغراق: ﴿فَأَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ أَنِ ٱضْرِب بِّعَصَاكَ ٱلْبَحْرَ ۖ فَٱنفَلَقَ﴾ [الشعراء: ٦٣]، ﴿وَأَنجَيْنَا مُوسَىٰ وَمَن مَّعَهُۥٓ أَجْمَعِينَ﴾ [الشعراء: ٦٥] ﴿ثُمَّ أَغْرَقْنَا ٱلْءَاخَرِينَ﴾ [الشعراء: ٦٥-٦٦]. وقولُ فرعونَ عند الغرق ﴿ءَامَنتُ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا ٱلَّذِىٓ ءَامَنَتْ بِهِۦ بَنُوٓا۟ إِسْرَٰٓءِيلَ﴾ [يونس: ٩٠] رُدَّ عليه في الآية بعدَها: ﴿ءَآلْـَٰٔنَ وَقَدْ عَصَيْتَ قَبْلُ وَكُنتَ مِنَ ٱلْمُفْسِدِينَ﴾ [يونس: ٩٠-٩١].'
  WHERE id = '0af047b6-d0c1-497e-8a32-4ad2ef29838a';
UPDATE qa_questions SET evidence = 'القصّةُ مسوقةٌ في سورة يوسف متّصلةً، وسمّاها اللهُ ﴿أَحْسَنَ ٱلْقَصَصِ﴾ [يوسف: ٣]. وأطوارُها بمواضعها: الحسدُ ﴿إِذْ قَالُوا۟ لَيُوسُفُ وَأَخُوهُ أَحَبُّ إِلَىٰٓ أَبِينَا مِنَّا وَنَحْنُ عُصْبَةٌ﴾ [يوسف: ٨]؛ والجُبُّ ﴿فَلَمَّا ذَهَبُوا۟ بِهِۦ وَأَجْمَعُوٓا۟ أَن يَجْعَلُوهُ فِى غَيَٰبَتِ ٱلْجُبِّ﴾ [يوسف: ١٥]؛ والبيعُ ﴿وَشَرَوْهُ بِثَمَنٍۭ بَخْسٍۢ دَرَٰهِمَ مَعْدُودَةٍۢ﴾ [يوسف: ٢٠] — ومصرُ إنّما ذُكرت في المشتري لا في البائعين: ﴿وَقَالَ ٱلَّذِى ٱشْتَرَىٰهُ مِن مِّصْرَ لِٱمْرَأَتِهِۦٓ أَكْرِمِى مَثْوَىٰهُ﴾ [يوسف: ٢١]؛ والسجنُ بعد استعصامه ﴿قَالَ رَبِّ ٱلسِّجْنُ أَحَبُّ إِلَىَّ مِمَّا يَدْعُونَنِىٓ إِلَيْهِ﴾ [يوسف: ٣٣] ﴿ثُمَّ بَدَا لَهُم مِّنۢ بَعْدِ مَا رَأَوُا۟ ٱلْءَايَٰتِ لَيَسْجُنُنَّهُۥ حَتَّىٰ حِينٍۢ﴾ [يوسف: ٣٥]؛ والتمكينُ ﴿قَالَ ٱجْعَلْنِى عَلَىٰ خَزَآئِنِ ٱلْأَرْضِ ۖ إِنِّى حَفِيظٌ عَلِيمٌۭ﴾ [يوسف: ٥٥] ﴿وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِى ٱلْأَرْضِ﴾ [يوسف: ٥٥-٥٦]؛ والعفوُ ﴿قَالَ لَا تَثْرِيبَ عَلَيْكُمُ ٱلْيَوْمَ ۖ يَغْفِرُ ٱللَّهُ لَكُمْ﴾ [يوسف: ٩٢].'
  WHERE id = '0dcbef2e-03ef-4d1f-ad4c-11da0e575209';
UPDATE qa_questions SET evidence = '🔑 **العيبُ الأكبر — عددٌ سوّى بين روايتين متغايرتين وأسقط إحداهما**: قال الجواب ‹(33 مرة لكل واحدة)›، وليس في الصحيحين روايةٌ واحدةٌ يجتمع فيها الثلاثةُ على ثلاثٍ وثلاثين ثم يُنسب ذلك إليهما معًا؛ بل البخاري ٦٣١٨ يجعلها ثلاثًا وثلاثين في الثلاثة: «فَكَبِّرَا ثَلَاثًا وَثَلَاثِينَ، وَسَبِّحَا ثَلَاثًا وَثَلَاثِينَ، وَاحْمَدَا ثَلَاثًا وَثَلَاثِينَ»، ثم **يُعقِّب في الموضع نفسِه** بما يخالفه عن ابن سيرين: «التَّسْبِيحُ أَرْبَعٌ وَثَلَاثُونَ»؛ ومسلمٌ ٢٧٢٧ يجعل الزيادة في التكبير: «أن تكبرا الله أربعا وثلاثين. وتسبحاه ثلاثا وثلاثين. وتحمداه ثلاثا وثلاثين» ⇒ فنُسبت الروايتان إلى موضعيهما ولم يُطوَ اختلافُهما في عبارةٍ واحدة. 🔑 **والعيبُ الثاني أنّ ‹المعوذتين› ثنّاها الجوابُ والنصُّ ثلاثٌ**: البخاري ٥٠١٧ صريحٌ بضمّ الإخلاص إليهما: «فَقَرَأَ فِيهِمَا: ﴿قُلْ هُوَ اللهُ أَحَدٌ﴾ [الإخلاص: ١]، وَ ﴿قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ﴾ [الفلق: ١]، وَ ﴿قُلْ أَعُوذُ بِرَبِّ النَّاسِ﴾ [الناس: ١]»، وترجم له البخاري بـ‹باب فضل المعوذات› بالجمع لا بالتثنية؛ ومع ذلك **سقطت كيفيّتُها كلُّها** من الجواب وهي منصوصة: «جَمَعَ كَفَّيْهِ ثُمَّ نَفَثَ فِيهِمَا»، «ثُمَّ يَمْسَحُ بِهِمَا مَا اسْتَطَاعَ مِنْ جَسَدِهِ، يَبْدَأُ بِهِمَا عَلَى رَأْسِهِ وَوَجْهِهِ»، «يَفْعَلُ ذَلِكَ ثَلَاثَ مَرَّاتٍ». 🚩 **وأجمعُ أذكار النوم في الصحيحين سقط رأسًا**: دعاءُ البراء بن عازب (البخاري ٢٤٧) وفيه الوضوءُ والاضطجاعُ على الشقّ الأيمن ووصيّةُ الختم «وَاجْعَلْهُنَّ آخِرَ مَا تَتَكَلَّمُ بِهِ»، بل فيه **تصحيحُ النبيّ ﷺ للفظِ الذاكر**: «قُلْتُ: وَرَسُولِكَ، قَالَ: لَا، وَنَبِيِّكَ الَّذِي أَرْسَلْتَ» — وهو أصلٌ في وجوب التزام اللفظ المأثور. وسقط كذلك «بِاسْمِكَ اللَّهُمَّ أَمُوتُ وَأَحْيَا» (البخاري ٦٣٢٤). 🚩 و`evidence` كان عبارةً إنشائيّةً واحدة (‹ثبتت هذه الأذكار في أحاديث صحيحة متعددة عند النوم›) بلا رقمٍ ولا موضعٍ ولا لفظ.'
  WHERE id = '15d97eaa-b63d-4634-8651-0f3742cf1431';
UPDATE qa_questions SET evidence = 'نصُّ الآيتين برسم المصحف: ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لِمَ تَقُولُونَ مَا لَا تَفْعَلُونَ﴾ [الصف: ٢] ﴿كَبُرَ مَقْتًا عِندَ ٱللَّهِ أَن تَقُولُوا۟ مَا لَا تَفْعَلُونَ﴾ [الصف: ٢-٣] — والآيةُ الثانيةُ صرّحت بأنّ ذلك ‹كَبُرَ مَقْتًا عِندَ ٱللَّهِ›، وهو أشدُّ من مجرّد الذمّ. وأمّا كونُ الحجّة قد تكون على صاحبها، فلفظُه المحفوظُ في القرآن خاصّةً لا في مطلق العلم: «وَالْقُرْآنُ حُجَّةٌ لَكَ أو عليك» من حديث أبي مالك الأشعريّ (مسلم ٢٢٣، ج١/ص٢٠٣، باب فضل الوضوء).'
  WHERE id = '358aca26-5e36-4bd4-a223-62ef210b46de';
UPDATE qa_questions SET evidence = 'حدُّه عند ابن قدامة: «فأمَّا الإِيلاءُ فى الشَّرْعِ، فهو الحَلِفُ على تَرْكِ وَطْءِ المَرْأَةِ. والأصْلُ فِيهِ قولُ اللَّهِ تعالى» ثم ساق الآية (المغني، ج١١/ص٥)، وقيدُ المدّة في متن الخِرَقيّ الذي شرحه: «وَالْمُولِى الَّذِى يَحْلِفُ بِاللَّهِ عَزَّ وَجَلَّ أَنْ لَا يَطَأَ زوْجَتَهُ أَكْثَرَ مِنْ أَرْبَعَةِ أَشْهُرٍ». والأصلُ ﴿لِّلَّذِينَ يُؤْلُونَ مِن نِّسَآئِهِمْ تَرَبُّصُ أَرْبَعَةِ أَشْهُرٍۢ ۖ فَإِن فَآءُو فَإِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌۭ﴾ [البقرة: ٢٢٦] ﴿وَإِنْ عَزَمُوا۟ ٱلطَّلَٰقَ فَإِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌۭ﴾ [البقرة: ٢٢٦-٢٢٧] — وآيةُ ٢٢٧ هي موضعُ شقِّ الحكم الثاني، وكانت ساقطةً من الشاهد. وبعد انقضاء المدّة: «طُولِبَ بالفَيْئَةِ … فإنْ لم يَفعَلْ، أُمِرَ بالطَّلاقِ»، و«ويُؤْخَذُ بالفَيْئةِ، أو بالطلاقِ» (المغني، ج١١/ص٤٤).'
  WHERE id = '3c21aed8-7cc7-446c-8c5b-fab2f98baf58';
UPDATE qa_questions SET evidence = 'أصحابُ الفروض أشخاصٌ سمّى اللهُ لهم أنصبةً مقدَّرةً، والمنصوصُ عليهم في ثلاث آيات: (١) النساء ١١ وفيها البناتُ والبنتُ والأبوان: ﴿فَإِن كُنَّ نِسَآءًۭ فَوْقَ ٱثْنَتَيْنِ فَلَهُنَّ ثُلُثَا مَا تَرَكَ ۖ وَإِن كَانَتْ وَٰحِدَةًۭ فَلَهَا ٱلنِّصْفُ ۚ وَلِأَبَوَيْهِ لِكُلِّ وَٰحِدٍۢ مِّنْهُمَا ٱلسُّدُسُ مِمَّا تَرَكَ إِن كَانَ لَهُۥ وَلَدٌۭ ۚ فَإِن لَّمْ يَكُن لَّهُۥ وَلَدٌۭ وَوَرِثَهُۥٓ أَبَوَاهُ فَلِأُمِّهِ ٱلثُّلُثُ﴾ [النساء: ١١]؛ (٢) والنساء ١٢ وفيها الزوجُ والزوجاتُ ثم أخٌ أو أختٌ: ﴿وَلَكُمْ نِصْفُ مَا تَرَكَ أَزْوَٰجُكُمْ إِن لَّمْ يَكُن لَّهُنَّ وَلَدٌۭ﴾ [النساء: ١٢] … ﴿وَلَهُنَّ ٱلرُّبُعُ مِمَّا تَرَكْتُمْ إِن لَّمْ يَكُن لَّكُمْ وَلَدٌۭ ۚ فَإِن كَانَ لَكُمْ وَلَدٌۭ فَلَهُنَّ ٱلثُّمُنُ﴾ [النساء: ١٢] … ﴿وَلَهُۥٓ أَخٌ أَوْ أُخْتٌۭ فَلِكُلِّ وَٰحِدٍۢ مِّنْهُمَا ٱلسُّدُسُ﴾ [النساء: ١٢]؛ (٣) والنساء ١٧٦ وفيها الأختُ فصاعدًا: ﴿وَلَهُۥٓ أُخْتٌۭ فَلَهَا نِصْفُ مَا تَرَكَ﴾ [النساء: ١٧٦] ﴿فَإِن كَانَتَا ٱثْنَتَيْنِ فَلَهُمَا ٱلثُّلُثَانِ مِمَّا تَرَكَ﴾ [النساء: ١٧٦]. وتعيينُ الأخوَينِ المُبهَمَين في الآيتين منصوصٌ عند ابن قدامة: في آية الكلالة الأخيرة «والمُرَادُ بذلك الإِخْوَةُ والأَخَوَاتُ مِن الأَبَوَيْنِ، أو مِن الأَبِ، بلا خِلافٍ بينَ أهْلِ العِلْمِ» (المغني، ج٩/ص٦)، وفي النساء ١٢ «والمُرَادُ بِهَذِه الآيةِ الْأَخُ والأُخْتُ مِنْ الأُمِّ، بإجْماعِ أَهْلِ الْعِلْمِ» (المغني، ج٩/ص٧).'
  WHERE id = '53f94ba7-bb78-4557-9000-3037eba1cced';
UPDATE qa_questions SET evidence = 'المغني ج١٠/ص٥٤٧: «وأجْمَعَ أَهْلُ الْعِلْمِ أَنَّ الْحُرَّ إِذَا طَلَّق الْحُرَّةَ دُونَ الثَّلَاثِ، أو الْعَبْدَ إِذا طَلَّقَ دُونَ الاثْنَتَيْنِ، أَنَّ لهما الرَّجْعَةَ فى العِدَّةِ». وج١٠/ص٥٤٨ في غير المدخول بها ومن انقضت عدتها: «فتَبِينُ بِمُجَرَّدِ طَلاقِهَا، وتَصِيرُ كَالْمَدْخُولِ بها بعدَ انْقِضاءِ عِدَّتِها، لا رَجْعَةَ عليها، ولا نَفقَةَ لها. وإِنْ رَغِبَ مُطَلِّقُهَا فيها فهو خاطِبٌ مِن الْخُطَّابِ، يَتَزَوَّجُها بِرِضَاها بِنِكاحٍ جَدِيدٍ، وتَرْجِعُ إليه بطَلْقَتَيْنِ». وفي المطلقة ثلاثًا: «وَلا خِلافَ بينهم فِى أَنَّ المُطَلَّقَةَ ثَلاثًا بعدَ الدُّخُولِ، لا تَحِلُّ له حَتَّى تَنْكِحَ زَوْجًا غيرَهُ» لقوله تعالى ﴿فَإِنْ طَلَّقَهَا فَلَا تَحِلُّ لَهُ مِنْ بَعْدُ حَتَّى تَنْكِحَ زَوْجًا غَيْرَهُ﴾ [البقرة: ٢٣٠].'
  WHERE id = '5cac702c-c4fb-44c6-ac1e-273f611ed758';
UPDATE qa_questions SET evidence = 'المغني ج١٤/ص١٢، ولفظ الخِرَقي: «وَلَا يُوَلَّى قَاضٍ حَتَّى يَكُونَ بَالِغًا، عَاقِلًا، مُسْلِمًا، حُرًّا، عَدْلًا، عَالِمًا، فَقِيهًا، وَرِعًا»، قال ابن قدامة: «وجُمْلتُه أنَّه يُشْتَرطُ في القاضي ثَلاثةُ شروطٍ؛ أحدها، الكَمالُ، وهو نوعان؛ كمالُ الأحْكام، وكمالُ الخِلْقَةِ، أمَّا كمالُ الأحكامِ فيُعتَبرُ في أربعةِ أشياء؛ أنْ يكونَ بَالغًا عاقِلًا حُرًّا ذكَرًا». وج١٤/ص١٣: «وأما كمالُ الخِلْقةِ، فأنْ يكونَ مُتَكلِّمًا سميعًا بصيرًا؛ لأنَّ الأخْرَسَ لا يُمْكِنُه النُّطْقُ بالحُكْمِ… والأصَمَّ لا يَسْمعُ قولَ الخَصْمَينِ، والأعْمَى لا يعْرِفُ المُدَّعِىَ مِن المُدَّعَى عليه»، و«الشرط الثاني، العدالةُ، فلا يجوزُ تَوْلِيَةُ فاسقٍ، ولا مَن فيه نَقْصٌ يَمْنَعُ الشَّهادةَ». وج١٤/ص١٤: «الشرط الثالث، أنْ يكونَ من أهلِ الاجْتهادِ. وبهذا قال مالكٌ، والشافعيُّ، وبعضُ الحنفيَّةِ. وقالَ بعضُهم: يجوزُ أن يكونَ عامِّيًّا فيَحْكمَ بالتَّقْليدِ… ولَنا، قولُ اللهِ تعالى: ﴿وَأَنِ احْكُمْ بَيْنَهُمْ بِمَا أَنْزَلَ اللَّهُ﴾ [المائدة: ٤٩]. ولم يقُلْ بالتَّقْليدِ»، وحديث بريدة: «القُضَاةُ ثَلَاثَةٌ؛ اثْنَانِ فِي النَّارِ، وَوَاحِدٌ فِي الْجَنَّةِ… وَرَجُلٌ قَضَى لِلنَّاسِ عَلَى جَهْلٍ، فَهُوَ فِي النَّارِ» رواه ابن ماجه، «والعامِّيُّ يقْضِي على الجَهْلِ».'
  WHERE id = '6934b828-f91b-4579-abe6-dc4255d076ab';
UPDATE qa_questions SET evidence = 'عقد مسلمٌ لهذا بابَ وجوب الطهارة للصلاة (ج١/ص٢٠٤)، وفيه حديثُ ابن عمر ٢٢٤: «لَا تُقْبَلُ صَلَاةٌ بِغَيْرِ طُهُورٍ. وَلَا صَدَقَةٌ مِنْ غُلُولٍ»، وحديثُ أبي هريرة ٢٢٥ في الموضع نفسِه: «لَا تُقْبَلُ صَلَاةُ أَحَدِكُمْ، إِذَا أَحْدَثَ، حَتَّى يتوضأ». وأصلُه من الكتاب ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا قُمْتُمْ إِلَى ٱلصَّلَوٰةِ فَٱغْسِلُوا۟ وُجُوهَكُمْ وَأَيْدِيَكُمْ إِلَى ٱلْمَرَافِقِ وَٱمْسَحُوا۟ بِرُءُوسِكُمْ وَأَرْجُلَكُمْ إِلَى ٱلْكَعْبَيْنِ﴾ [المائدة: ٦]، وفي الآية نفسِها أن موجَبَ الجنابة الاغتسالُ ﴿وَإِن كُنتُمْ جُنُبًۭا فَٱطَّهَّرُوا۟﴾ [المائدة: ٦]، وأن بدلَ الماء عند فقده التيمُّمُ ﴿فَلَمْ تَجِدُوا۟ مَآءًۭ فَتَيَمَّمُوا۟ صَعِيدًۭا طَيِّبًۭا فَٱمْسَحُوا۟ بِوُجُوهِكُمْ وَأَيْدِيكُم مِّنْهُ﴾ [المائدة: ٦].'
  WHERE id = '69e6b7b0-db1e-435f-91d0-9c567bd862c9';
UPDATE qa_questions SET evidence = 'قال الله تعالى: ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱذْكُرُوا۟ نِعْمَةَ ٱللَّهِ عَلَيْكُمْ إِذْ جَآءَتْكُمْ جُنُودٌۭ فَأَرْسَلْنَا عَلَيْهِمْ رِيحًۭا وَجُنُودًۭا لَّمْ تَرَوْهَا﴾ [الأحزاب: ٩] ﴿إِذْ جَآءُوكُم مِّن فَوْقِكُمْ وَمِنْ أَسْفَلَ مِنكُمْ وَإِذْ زَاغَتِ ٱلْأَبْصَٰرُ وَبَلَغَتِ ٱلْقُلُوبُ ٱلْحَنَاجِرَ﴾ [الأحزاب: ٩-١٠]. وأصلُ التسمية في السيرة: قال ابن إسحاق في نفَرٍ من يهود بني النضير وبني وائل خرجوا إلى قريش يدعونهم إلى حرب النبي صلى الله عليه وسلم: «وَهُمْ الَّذِينَ حَزَّبُوا الْأَحْزَابَ عَلَى رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ» (ج٢/ص٢١٤)، ثم عدَّ الخارجين: «فَخَرَجَتْ قُرَيْشٌ، وَقَائِدُهَا أَبُو سُفْيَانَ بْنُ حَرْبٍ، وَخَرَجَتْ غَطَفَانُ، وَقَائِدُهَا عُيَيْنَةُ بْنُ حِصْنِ بْنِ حُذَيْفَةَ بْنِ بَدْرٍ» ... «وَالْحَارِثُ ابْن عَوْفِ بْنِ أَبِي حَارِثَةَ الْمُرِّيُّ، فِي بَنِي مُرَّةَ» (ج٢/ص٢١٥). وأما اسمُها الآخر فمن الخطّة الدفاعيّة: «ثُمَّ كَانَتْ غَزْوَةُ الْخَنْدَقِ فِي شَوَّالٍ سَنَةَ خَمْسٍ» (ج٢/ص٢١٤)، «ضَرَبَ الْخَنْدَقَ عَلَى الْمَدِينَةِ، فَعَمِلَ فِيهِ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَرْغِيبًا لِلْمُسْلِمِينَ فِي الْأَجْرِ، وَعَمِلَ مَعَهُ الْمُسْلِمُونَ فِيهِ» (ج٢/ص٢١٦). ونسبةُ المشورة إلى سلمان ذكرها ابن هشام بصيغة التمريض: «قَالَ ابْنُ هِشَامٍ: يُقَالُ: إنَّ سَلْمَانَ الْفَارِسِيَّ أَشَارَ بِهِ عَلَى رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ» (ج٢/ص٢٢٤).'
  WHERE id = '7d8a6cc6-492f-4a45-be25-57080f815cdf';
UPDATE qa_questions SET evidence = 'نصَّ ابن قدامة على حصرها وعددِها في باب أصول سهام الفرائض: «وأصولُ المسائل كلُّها سَبعَةٌ؛ لأنَّ الفروضَ المحدودةَ في كتابِ اللَّه تعالى ستةٌ؛ النِّصْفُ، والرُّبْعُ، والثُمُنُ، والثُّلُثانِ، والثُّلُثُ، والسُّدُسُ» (المغني، ج٩/ص٣٥). ومواضعُها من الكتاب: النصفُ ﴿وَإِن كَانَتْ وَٰحِدَةًۭ فَلَهَا ٱلنِّصْفُ﴾ [النساء: ١١]، والربعُ والثمنُ ﴿فَإِن كَانَ لَهُنَّ وَلَدٌۭ فَلَكُمُ ٱلرُّبُعُ مِمَّا تَرَكْنَ﴾ [النساء: ١٢] ﴿فَإِن كَانَ لَكُمْ وَلَدٌۭ فَلَهُنَّ ٱلثُّمُنُ﴾ [النساء: ١٢]، والثلثان ﴿فَإِن كُنَّ نِسَآءًۭ فَوْقَ ٱثْنَتَيْنِ فَلَهُنَّ ثُلُثَا مَا تَرَكَ﴾ [النساء: ١١]، والثلثُ ﴿وَوَرِثَهُۥٓ أَبَوَاهُ فَلِأُمِّهِ ٱلثُّلُثُ﴾ [النساء: ١١]، والسدسُ ﴿وَلِأَبَوَيْهِ لِكُلِّ وَٰحِدٍۢ مِّنْهُمَا ٱلسُّدُسُ مِمَّا تَرَكَ إِن كَانَ لَهُۥ وَلَدٌۭ﴾ [النساء: ١١].'
  WHERE id = '9cdf8612-752b-42b3-ba35-317fb911d16d';
UPDATE qa_questions SET evidence = 'كشاف القناع ج١/ص٢٤٨: «(وَهِيَ) أَيْ: شُرُوطُ الصَّلَاةِ (تِسْعَةٌ: الْإِسْلَامُ، وَالْعَقْلُ، وَالتَّمْيِيزُ) وَهَذِهِ الثَّلَاثَةُ شَرْطٌ فِي كُلِّ عِبَادَةٍ وَلِذَلِكَ أَسْقَطَهَا فِي الْمُقْنِعِ وَغَيْرِهِ»، ثم «الرَّابِعُ (الطَّهَارَةُ مِنْ الْحَدَثِ) الْأَكْبَرِ وَالْأَصْغَرِ» لقوله ﷺ: «لَا يَقْبَلُ اللَّهُ صَلَاةً بِغَيْرِ طُهُورٍ» رواه مسلم. وج١/ص٢٤٩: «(وَالْخَامِسُ دُخُولُ الْوَقْتِ)» لقوله تعالى ﴿أَقِمِ الصَّلاةَ لِدُلُوكِ الشَّمْسِ﴾ [الإسراء: ٧٨]. وج١/ص٢٦٣: «(وَهُوَ) أَيْ: سَتْرُ الْعَوْرَةِ. (الشَّرْطُ السَّادِسُ)». وج١/ص٢٨٨: «(الشَّرْطُ السَّابِعُ) لِلصَّلَاةِ لِتَقَدُّمِ سِتَّةٍ قَبْلَهُ (طَهَارَةُ بَدَنِ الْمُصَلِّي وَ) طَهَارَةُ (ثِيَابِهِ وَ) طَهَارَةُ (مَوْضِعِ صَلَاتِهِ… مِنْ نَجَاسَةٍ غَيْرِ مَعْفُوٍّ عَنْهَا) وَعَدَمِ حَمْلِهَا (شَرْطٌ لِصِحَّةِ الصَّلَاةِ)». وج١/ص٣٠٢ في الاستقبال: «(وَهُوَ الشَّرْطُ الثَّامِنُ لِصِحَّةِ الصَّلَاةِ) لِأَنَّهُ قَدْ تَقَدَّمَ عَلَيْهِ سَبْعَةٌ (فَلَا تَصِحُّ) الصَّلَاةُ (بِدُونِهِ)». وج١/ص٣١٣ في النية: «(وَهِيَ الشَّرْطُ التَّاسِعُ) وَبِهَا تَمَّتْ شُرُوطُ الصَّلَاةِ». وحكمُ الإخلال بها ج١/ص٢٤٨: «(فَمَتَى أَخَلَّ بِشَرْطٍ لِغَيْرِ عُذْرٍ لَمْ تَنْعَقِدْ صَلَاتُهُ) لِفَقْدِ شَرْطِهَا (وَلَوْ) كَانَ التَّارِكُ لِلشَّرْطِ (نَاسِيًا) لَهُ (أَوْ جَاهِلًا) بِهِ».'
  WHERE id = 'a113f9f8-b6dc-4319-a0b3-221745dd439d';
UPDATE qa_questions SET evidence = 'الآيتان بتمامهما: ﴿وَقَضَىٰ رَبُّكَ أَلَّا تَعْبُدُوٓا۟ إِلَّآ إِيَّاهُ وَبِٱلْوَٰلِدَيْنِ إِحْسَٰنًا ۚ إِمَّا يَبْلُغَنَّ عِندَكَ ٱلْكِبَرَ أَحَدُهُمَآ أَوْ كِلَاهُمَا فَلَا تَقُل لَّهُمَآ أُفٍّۢ وَلَا تَنْهَرْهُمَا وَقُل لَّهُمَا قَوْلًۭا كَرِيمًۭا﴾ [الإسراء: ٢٣] ﴿وَٱخْفِضْ لَهُمَا جَنَاحَ ٱلذُّلِّ مِنَ ٱلرَّحْمَةِ وَقُل رَّبِّ ٱرْحَمْهُمَا كَمَا رَبَّيَانِى صَغِيرًۭا﴾ [الإسراء: ٢٣-٢٤]. وقال ابن كثير عندها: «ولهذا قرن بعبادته بر الوالدين فقال: (وَبِالْوَالِدَيْنِ إِحْسَانًا) أي: وأمر بالوالدين إحسانًا»، ثم فسّر النهيَ: «(فَلا تَقُلْ لَهُمَا أُفٍّ) أي: لا تسمعهما قولا سيئًا، حتى ولا التأفيف الذي هو أدنى مراتب القول السيئ (وَلا تَنْهَرْهُمَا) أي: ولا يصدر منك إليهما فعل قبيح» (ج٥/ص٦٤). وساق في الموضع نفسِه حديثَ أبي أسيدٍ الساعديّ في برِّهما بعد موتهما: «نعم، خصال أربع: الصلاة عليهما، والاستغفار لهما، وإنفاذ عهدهما، وإكرام صديقهما، وصلة الرحم التي لا رحم لك إلا من قبلهما» رواه أحمد وأبو داود وابن ماجه (ج٥/ص٦٦).'
  WHERE id = 'a8a97cbc-5771-49bc-8be7-cf1f84fd4670';
UPDATE qa_questions SET evidence = 'المغني ج١٣/ص٦٠٥: «وإِنْ حَلَفَ لا يَدْخُلُ بيتًا، فدَخَلَ مَسْجدًا، أو حَمَّامًا، فإنَّه يَحْنَثُ. نَصَّ عليه أحمدُ. ويَحْتَمِلُ أَنْ لا يَحْنَثَ. وهو قولُ أكثرِ الفُقَهاءِ؛ لأنَّه لا يُسَمَّى بَيْتًا فى العُرْفِ… والأَوَّلُ المذهبُ، لأَنَّهما بَيْتانِ حقيقَةً، وقد سَمَّى اللَّه المساجِدَ بُيوتًا، فقال: ﴿فِى بُيُوتٍ أَذِنَ اللَّهُ أَنْ تُرْفَعَ﴾ [النور: ٣٦]». وأصلُ تحكيم النية عنده ج١٣/ص٥٤٤: «وإذا احْتَمَلَه اللَّفْظُ، وَجَبَ صَرْفُ اليَمِينِ إليه؛ لقولِ النَّبِىِّ ﷺ: "إنَّما لِامْرِئٍ مَا نَوَى"».'
  WHERE id = 'aff54ee5-493e-4823-b946-b50dc8f9b54d';
UPDATE qa_questions SET evidence = 'كشاف القناع ج٢/ص٥٢١: «(فَصْلٌ أَرْكَانُ الْحَجِّ) أَرْبَعَةٌ (الْوُقُوفُ بِعَرَفَةَ) لِحَدِيثِ «الْحَجُّ عَرَفَةَ»… (وَطَوَافُ الزِّيَارَةِ) قَالَ ابْنُ عَبْدِ الْبَرِّ: هُوَ مِنْ فَرَائِضَ الْحَجِّ لَا خِلَافَ فِي ذَلِكَ بَيْنَ الْعُلَمَاءِ لِقَوْلِهِ تَعَالَى ﴿وَلْيَطَّوَّفُوا بِالْبَيْتِ الْعَتِيقِ﴾ [الحج: ٢٩] (وَالسَّعْيُ) بَيْنَ الصَّفَا وَالْمَرْوَةِ… (وَالْإِحْرَامُ وَهُوَ النِّيَّةُ) أَيْ: نِيَّةُ النُّسُكِ» لحديث «إنَّمَا الْأَعْمَالُ بِالنِّيَّاتِ». وفي واجباته: «(وَوَاجِبَاتُهُ) أَيْ: الْحَجِّ (سَبْعَةٌ: الْإِحْرَامُ مِنْ الْمِيقَاتِ)… (وَالْوُقُوفُ بِعَرَفَةَ إلَى اللَّيْلِ)… (وَالْمَبِيتُ بِمُزْدَلِفَةَ)… (وَالْمَبِيتُ بِمِنًى)… (وَالرَّمْيُ) لِلْجِمَارِ (مُرَتَّبًا)… (وَالْحِلَاقُ أَوْ التَّقْصِيرُ وَطَوَافُ الْوَدَاعِ)»، و«(وَأَرْكَانُ الْعُمْرَةِ) ثَلَاثَةٌ (الْإِحْرَامُ، وَالطَّوَافُ وَالسَّعْيُ)»، ثم الفرقُ بينهما: «(فَمَنْ تَرَكَ رُكْنًا، أَوْ) تَرَكَ (النِّيَّةَ لَهُ) إنْ اُعْتُبِرَتْ فِيهِ كَالطَّوَافِ وَالسَّعْيِ (لَمْ يَتِمَّ نُسُكُهُ إلَّا بِهِ)». وج٢/ص٥٢٢: «(وَمَنْ تَرَكَ وَاجِبًا) لِحَجٍّ أَوْ عُمْرَةٍ (وَلَوْ سَهْوًا فَعَلَيْهِ دَمٌ)»، و«(وَمَنْ تَرَكَ سُنَّةً فَلَا شَيْءَ عَلَيْهِ)».'
  WHERE id = 'c0008bac-c54a-45cf-a6da-e2e190eda17a';
UPDATE qa_questions SET evidence = '﴿وَإِذْ أَخَذْنَا مِنَ ٱلنَّبِيِّۦنَ مِيثَٰقَهُمْ وَمِنكَ وَمِن نُّوحٍۢ وَإِبْرَٰهِيمَ وَمُوسَىٰ وَعِيسَى ٱبْنِ مَرْيَمَ ۖ وَأَخَذْنَا مِنْهُم مِّيثَٰقًا غَلِيظًۭا﴾ [الأحزاب: ٧]. قال السعديُّ عند هذه الآية: «يخبر تعالى أنه أخذ من النبيين عمومًا، ومن أولي العزم -وهم، هؤلاء الخمسة المذكورون- خصوصًا، ميثاقهم الغليظ وعهدهم الثقيل المؤكد، على القيام بدين الله والجهاد في سبيله» (ص٦٥٩). فالخمسةُ هم المسمَّوْن في الآية نفسِها، والنبيُّ ﷺ داخلٌ فيهم بقوله ﴿وَمِنكَ﴾ [الأحزاب: ٧].'
  WHERE id = 'e69c576d-27c2-4c52-9586-abd27f088c28';
UPDATE qa_questions SET evidence = 'الآيةُ بتمامها لا مبتورةً عند ‹فَوَٰحِدَةً›: ﴿وَإِنْ خِفْتُمْ أَلَّا تُقْسِطُوا۟ فِى ٱلْيَتَٰمَىٰ فَٱنكِحُوا۟ مَا طَابَ لَكُم مِّنَ ٱلنِّسَآءِ مَثْنَىٰ وَثُلَٰثَ وَرُبَٰعَ ۖ فَإِنْ خِفْتُمْ أَلَّا تَعْدِلُوا۟ فَوَٰحِدَةً أَوْ مَا مَلَكَتْ أَيْمَٰنُكُمْ ۚ ذَٰلِكَ أَدْنَىٰٓ أَلَّا تَعُولُوا۟﴾ [النساء: ٣] — وقولُه ﴿ذَٰلِكَ أَدْنَىٰٓ أَلَّا تَعُولُوا۟﴾ [النساء: ٣] هو تعليلُ الاقتصار، وكان ساقطًا بالبَتْر. وحدُّ الأربع منصوصٌ عند ابن قدامة: «ولا يَمْلِكُ إمْساكَ أكثَر من أربعٍ»، ودليلُه «ما رَوَى قَيْسُ بن الحارثِ، قال: أسْلَمْتُ وَتَحْتِى ثَمانِ نِسْوَةٍ، فأتَيْتُ النَّبِىَّ -صلى اللَّه عليه وسلم-، فقلتُ له ذلك، فقال: "اخْتَرْ مِنْهنَّ أرْبعًا"» رواه أحمد وأبو داود، وحديثُ غيلانَ بن سلمة «فأمَرَه رسولُ اللَّه -صلى اللَّه عليه وسلم- أن يتَخَيَّر منهنَّ أرْبعًا» رواه الترمذيّ (المغني، ج١٠/ص١٤).'
  WHERE id = 'eac5b364-dc63-4cfd-b2c8-d047ddb49c2a';
UPDATE qa_questions SET evidence = '🔑 **العيبُ الأكبر — فتنةُ القبر سقطت وهي في مفاتيح الصفّ نفسِه وأصلُ البابِ الذي يتفرّع عنه العذابُ والنعيم**: `keywords` الصفِّ ‹عذاب القبر، فتنة القبر›، والجوابُ لم يذكر السؤالَ ولا الملكين بحرف؛ والمنصوصُ أنّ المبدأ سؤالٌ ثم يترتّب عليه الأمران: البخاري ١٣٣٨ «أَتَاهُ مَلَكَانِ فَأَقْعَدَاهُ، فَيَقُولَانِ لَهُ: مَا كُنْتَ تَقُولُ فِي هَذَا الرَّجُلِ مُحَمَّدٍ ﷺ ؟»، وفيه جوابُ المؤمن وجوابُ الآخر: «لَا أَدْرِي، كُنْتُ أَقُولُ مَا يَقُولُ النَّاسُ». 🔑 **والعيبُ الثاني أنّ ‹نصوص متعددة صحيحة› سيقت بلا نصٍّ واحدٍ ولا موضع**، ومع ذلك فاتَه أصرحُ ما في الباب: تنصيصُ البخاري ١٣٦٩ على أنّ آية إبراهيم نزلت فيه بعينه: «﴿يُثَبِّتُ اللهُ الَّذِينَ آمَنُوا﴾ [إبراهيم: ٢٧] نَزَلَتْ فِي عَذَابِ الْقَبْرِ»، مقرونةً بسببها: «إِذَا أُقْعِدَ الْمُؤْمِنُ فِي قَبْرِهِ أُتِيَ، ثُمَّ شَهِدَ أَنْ لَا إِلَهَ إِلَّا اللهُ» — والآيةُ منقولةٌ **من داخل نصّ الحديث في صفحته** لا من موضعٍ آخر. 🚩 **و‹يُؤمَن به كما ورد دون تكييف كيفيته› جعل البابَ إجمالًا كلَّه، والنصُّ يُعيِّن سببين مضروبين مثلًا**: البخاري ٢١٨ «إِنَّهُمَا لَيُعَذَّبَانِ، وَمَا يُعَذَّبَانِ فِي كَبِيرٍ، أَمَّا أَحَدُهُمَا فَكَانَ لَا يَسْتَتِرُ مِنَ الْبَوْلِ، وَأَمَّا الْآخَرُ فَكَانَ يَمْشِي بِالنَّمِيمَةِ» ⇒ فالكيفيّةُ هي التي لا تُكيَّف، وأمّا الأسبابُ فمنصوصةٌ يُحذَّر منها. 🚩 **و`evidence` (‹كان النبي ﷺ يتعوذ من عذاب القبر في صلاته›) صحيحٌ بلا موضع، ومسلمٌ أصرحُ منه في أنه أمرٌ للأمّة لا فعلٌ منه فحسب**: مسلم ٥٨٨ «إِذَا تَشَهَّدَ أَحَدُكُمْ فَلْيَسْتَعِذْ بِاللَّهِ مِنْ أَرْبَعٍ»، ومحلُّ فعلِه ﷺ البخاري ٨٣٢. 🚩 وفي مسلم ٢٨٦٧ ما يفسِّر سببَ احتجاب هذا الغيب عنّا، ولم يُذكر: «فَلَوْلَا أَنْ لَا تَدَافَنُوا، لَدَعَوْتُ لله أَنْ يُسْمِعَكُمْ مِنْ عَذَابِ الْقَبْرِ الَّذِي أَسْمَعُ مِنْهُ»، وفيه أنّ الابتلاءَ في القبر عامٌّ لهذه الأمّة: «إن هذه الأمة تبتلى في قبورها».'
  WHERE id = 'f3432fb8-c8f5-4fe9-a025-9af8395128b9';
-- (٢) الحقل answer — ١٣ صفًّا
UPDATE qa_questions SET answer = 'الإيلاءُ في الشرع هو الحَلِف على ترك وطء المرأة، كما حدَّه ابن قدامة في المغني (ج١١/ص٥). وضابطُ المدّة في متن الخِرَقيّ: أن يحلف بالله أن لا يطأ زوجتَه أكثرَ من أربعة أشهر. وأصلُه قولُه تعالى: ﴿لِّلَّذِينَ يُؤْلُونَ مِن نِّسَآئِهِمْ تَرَبُّصُ أَرْبَعَةِ أَشْهُرٍۢ﴾ [البقرة: ٢٢٦]، فإن فاء فاللهُ غفورٌ رحيم، ﴿وَإِنْ عَزَمُوا۟ ٱلطَّلَٰقَ فَإِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌۭ﴾ [البقرة: ٢٢٦-٢٢٧]. فإذا انقضت المدّةُ طُولب بالفيئة، فإن لم يفعل أُمِر بالطلاق، فيُؤخَذ بالفيئة أو بالطلاق (المغني، ج١١/ص٤٤) — دفعًا للضرر عن الزوجة.'
  WHERE id = '3c21aed8-7cc7-446c-8c5b-fab2f98baf58';
UPDATE qa_questions SET answer = 'الرجعي: ما يملك فيه الزوج مراجعة زوجته في العدة بغير عقد جديد ولا مهر، وهو ما دون الثلاث من الحر (الطلقة الأولى والثانية)، وقد أجمع أهل العلم على ثبوت الرجعة فيه ما دامت في العدة. والبائن نوعان: بينونة صغرى — كغير المدخول بها ومن انقضت عدتها — فلا رجعة له عليها، وإن رغب فيها فهو خاطب من الخُطّاب يتزوجها برضاها بنكاح جديد وترجع إليه بما بقي من الطلقات؛ وبينونة كبرى بالطلقة الثالثة، فلا تحل له حتى تنكح زوجًا غيره نكاحًا صحيحًا يطؤها فيه، بلا خلاف بين أهل العلم، لقوله تعالى: ﴿فَإِنْ طَلَّقَهَا فَلَا تَحِلُّ لَهُ مِنْ بَعْدُ حَتَّى تَنْكِحَ زَوْجًا غَيْرَهُ﴾ [البقرة: ٢٣٠].'
  WHERE id = '5cac702c-c4fb-44c6-ac1e-273f611ed758';
UPDATE qa_questions SET answer = 'يُشترط في القاضي عند الحنابلة ثلاثة شروط: الأول الكمال، وهو نوعان — كمال الأحكام: أن يكون بالغًا عاقلًا حرًّا ذكرًا؛ وكمال الخِلقة: أن يكون متكلمًا سميعًا بصيرًا. والثاني العدالة، فلا تجوز تولية فاسق ولا من فيه نقص يمنع الشهادة. والثالث أن يكون من أهل الاجتهاد، وبه قال مالك والشافعي وبعض الحنفية. ومقتضى ذلك أنه لا يكفي أن يكون عاميًّا يحكم بالتقليد، خلافًا لمن أجازه؛ لقوله تعالى: ﴿وَأَنِ احْكُمْ بَيْنَهُمْ بِمَا أَنْزَلَ اللَّهُ﴾ [المائدة: ٤٩] ولم يقل بالتقليد، ولحديث بريدة: "القضاة ثلاثة؛ اثنان في النار، وواحد في الجنة… ورجل قضى للناس على جهل فهو في النار"، والعامي يقضي على جهل. والإسلام معتبر كذلك، كما نصّ عليه الخِرَقي في شروطه.'
  WHERE id = '6934b828-f91b-4579-abe6-dc4255d076ab';
UPDATE qa_questions SET answer = 'نعم، لا تصحُّ الصلاةُ بغير طهارةٍ: «لَا تُقْبَلُ صَلَاةٌ بِغَيْرِ طُهُورٍ» (مسلم ٢٢٤)، وترجم له مسلمٌ ببابِ وجوب الطهارة للصلاة (ج١/ص٢٠٤)، ومناطُ انتقاضها الحدثُ: «لَا تُقْبَلُ صَلَاةُ أَحَدِكُمْ، إِذَا أَحْدَثَ، حَتَّى يتوضأ» (مسلم ٢٢٥). ⚠️ والشرطُ ‹الطهارة› لا ‹الوضوء› وحدَه كما في صيغة السؤال: لفظُ الحديث «بِغَيْرِ طُهُورٍ» يعمُّ الوضوءَ من الحدث الأصغر، والغُسلَ من الجنابة ﴿وَإِن كُنتُمْ جُنُبًۭا فَٱطَّهَّرُوا۟﴾ [المائدة: ٦]، والتيمُّمَ عند فقد الماء ﴿فَلَمْ تَجِدُوا۟ مَآءًۭ فَتَيَمَّمُوا۟ صَعِيدًۭا طَيِّبًۭا﴾ [المائدة: ٦]. فقيدُ ‹عند القدرة› في الجواب السابق يُبيَّن على وجهه: العاجزُ عن الماء لا يسقط عنه الشرطُ، بل ينتقل إلى بدلِه المنصوص، لا أن يصلّيَ بلا طَهُور.'
  WHERE id = '69e6b7b0-db1e-435f-91d0-9c567bd862c9';
UPDATE qa_questions SET answer = 'يجوز للمسلم أن ينكح المحصَنةَ من أهل الكتاب بنصّ ﴿وَٱلْمُحْصَنَٰتُ مِنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ مِن قَبْلِكُمْ﴾ [المائدة: ٥]، والآيةُ قيّدت ذلك بإيتاء الأجور وبأن يكون الأزواجُ ﴿مُحْصِنِينَ غَيْرَ مُسَٰفِحِينَ وَلَا مُتَّخِذِىٓ أَخْدَانٍۢ﴾ [المائدة: ٥]. وقرّر ابن قدامة أنّ للمسلم أن يبتدئ نكاح كتابيّة (المغني، ج١٠/ص٣٢). وأمّا نكاحُ المسلمة من غير المسلم فممنوعٌ بنصّ الكتاب: ﴿وَلَا تُنكِحُوا۟ ٱلْمُشْرِكِينَ حَتَّىٰ يُؤْمِنُوا۟﴾ [البقرة: ٢٢١]، ﴿لَا هُنَّ حِلٌّۭ لَّهُمْ وَلَا هُمْ يَحِلُّونَ لَهُنَّ﴾ [الممتحنة: ١٠].'
  WHERE id = '7e84b591-b01f-47be-bd8c-6f1dad43a079';
UPDATE qa_questions SET answer = 'أساسُها عند ابن القيم في مدارج السالكين الاتِّباعُ لا الرأي: «فَإِنَّ تَزْكِيَةَ النُّفُوسِ مُسَلَّمٌ إِلَى الرُّسُلِ»، «فَالرُّسُلُ أَطِبَّاءُ الْقُلُوبِ. فَلَا سَبِيلَ إِلَى تَزْكِيَتِهَا وَصَلَاحِهَا إِلَّا مِنْ طَرِيقِهِمْ»؛ فمن «زَكَّى نَفْسَهُ بِالرِّيَاضَةِ وَالْمُجَاهَدَةِ وَالْخَلْوَةِ، الَّتِي لَمْ يَجِئْ بِهَا الرُّسُلُ: فَهُوَ كَالْمَرِيضِ الَّذِي عَالَجَ نَفْسَهُ بِرَأْيِهِ». وقد قابل الله بين الفلاح والخيبة بعد أن ألهم النفسَ الأمرين: ﴿وَنَفْسٍۢ وَمَا سَوَّىٰهَا﴾ [الشمس: ٧] ﴿فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَىٰهَا﴾ [الشمس: ٨] ﴿قَدْ أَفْلَحَ مَن زَكَّىٰهَا﴾ [الشمس: ٩] ﴿وَقَدْ خَابَ مَن دَسَّىٰهَا﴾ [الشمس: ١٠]؛ والتزكيةُ عنده رفعُ النفس «بِآدَابِهِ الَّتِي أَدَّبَ بِهَا رُسُلَهُ وَأَنْبِيَاءَهُ وَأَوْلِيَاءَهُ. وَهِيَ التَّقْوَى». وتعويدُ النفس داخلٌ في ذلك؛ فالخلق «يُمْكِنُ أَنْ يَقَعَ كَسْبِيًّا بِالتَّخَلُّقِ وَالتَّكَلُّفِ. حَتَّى يَصِيرَ لَهُ سَجِيَّةً وَمَلَكَةً».'
  WHERE id = '87bc99af-e8f3-4f7e-b366-a919214759ad';
UPDATE qa_questions SET answer = 'ضابطُه عند ابن القيم في إعلام الموقعين أصلٌ مثبَتٌ لا نفيٌ مجرَّد: «الأصل في العقود والمعاملات الصحة حتى يقوم دليل على البطلان والتحريم»، بخلاف العبادات فـ«الأصل في العبادات البطلان حتى يقوم دليل على الأمر»؛ فما سكت عنه الشارع منها «فهي عفو حتى يحرمها»، ولا يبطُل منها إلا «ما أبطله الشارع أو نهى عنه». وقد أمر الله بالوفاء بها: ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَوْفُوا۟ بِٱلْعُقُودِ﴾ [المائدة: ١]، ونهى عن أكل المال بالباطل مستثنيًا التجارةَ عن تراضٍ: ﴿لَا تَأْكُلُوٓا۟ أَمْوَٰلَكُم بَيْنَكُم بِٱلْبَٰطِلِ إِلَّآ أَن تَكُونَ تِجَٰرَةً عَن تَرَاضٍۢ مِّنكُمْ﴾ [النساء: ٢٩]، وحرَّم الربا بعينه: ﴿وَأَحَلَّ ٱللَّهُ ٱلْبَيْعَ وَحَرَّمَ ٱلرِّبَوٰا۟﴾ [البقرة: ٢٧٥]. والغررُ المنهيُّ عنه محدَّدٌ لا مطلق، فهو «ما لا يُقْدَر على تسليمه، سواء كان موجودًا أو معدومًا»، «وهذا من الميْسِر الذي حرّمه اللَّه ورسوله».'
  WHERE id = '984d613a-3d42-41bd-99e7-cb6c4a6a91fd';
UPDATE qa_questions SET answer = 'الذكرُ عند ابن القيم في الوابل الصيب بابٌ واسع: «وفي الذكر نحوٌ من مائة فائدة»، عدَّ منها أنه «يطرد الشيطان ويَقْمَعُه ويَكْسِرُه»، و«يُرضِي الرحمن»، و«يزيل الهم والغم عن القلب»، و«يجلب للقلب الفرح والسرور والبَسْط»، و«يورثه المحبة التي هي روح الإسلام، وقطبُ رَحى الدين، ومدار السعادة والنجاة» إذ «جعل سبب المحبة دوام الذكر»، و«يورثه المراقبة حتى يُدْخِلَه في باب الإحسان، فيعبد الله كأنه يراه، ولا سبيل للغافل عن الذِّكر إلى مقام الإحسان»، و«يورثه الإنابة، وهي الرجوع إلى الله». وطمأنينةُ القلوب في الآية مقرونةٌ بالإيمان: ﴿ٱلَّذِينَ ءَامَنُوا۟ وَتَطْمَئِنُّ قُلُوبُهُم بِذِكْرِ ٱللَّهِ ۗ أَلَا بِذِكْرِ ٱللَّهِ تَطْمَئِنُّ ٱلْقُلُوبُ﴾ [الرعد: ٢٨].'
  WHERE id = 'a66f8b19-2cfa-4320-a873-eb877ac49005';
UPDATE qa_questions SET answer = 'مقاصدُ النكاح المنصوصةُ في الآية ثلاثة: السكنُ ﴿لِّتَسْكُنُوٓا۟ إِلَيْهَا﴾ [الروم: ٢١]، والمودّةُ والرحمةُ ﴿وَجَعَلَ بَيْنَكُم مَّوَدَّةًۭ وَرَحْمَةً﴾ [الروم: ٢١]. وزاد السعدي في بيانها ما يحصل به من «الاستمتاع واللذة والمنفعة بوجود الأولاد وتربيتهم، والسكون إليها»، وقال: «فلا تجد بين أحد في الغالب مثل ما بين الزوجين من المودة والرحمة» (ص٦٣٩). وأمّا العفّةُ وإحصانُ الفرج فمقصدٌ رابعٌ نصَّ عليه الحديث: «مَنِ اسْتَطَاعَ الْبَاءَةَ فَلْيَتَزَوَّجْ، فَإِنَّهُ أَغَضُّ لِلْبَصَرِ وَأَحْصَنُ لِلْفَرْجِ» (البخاري، ١٩٠٥).'
  WHERE id = 'df203e32-c210-4dc0-a0ff-95b2ada270be';
UPDATE qa_questions SET answer = 'أولو العزم خمسةٌ، وتعيينُهم مأخوذٌ من الآية نفسِها لا من تعدادٍ خارجها: ﴿وَإِذْ أَخَذْنَا مِنَ ٱلنَّبِيِّۦنَ مِيثَٰقَهُمْ وَمِنكَ وَمِن نُّوحٍۢ وَإِبْرَٰهِيمَ وَمُوسَىٰ وَعِيسَى ٱبْنِ مَرْيَمَ﴾ [الأحزاب: ٧] — فهم: محمدٌ ﷺ (وهو المخاطَبُ بـ﴿وَمِنكَ﴾ [الأحزاب: ٧])، ونوحٌ، وإبراهيمُ، وموسى، وعيسى ابنُ مريم. قال السعديُّ: «ومن أولي العزم -وهم، هؤلاء الخمسة المذكورون- خصوصًا» (ص٦٥٩). والذي أُخذ عليهم هو «ميثاقهم الغليظ وعهدهم الثقيل المؤكد، على القيام بدين الله والجهاد في سبيله».'
  WHERE id = 'e69c576d-27c2-4c52-9586-abd27f088c28';
UPDATE qa_questions SET answer = 'أُبيح للرجل أن يجمع بين أربعٍ فأقلَّ بنصّ ﴿فَٱنكِحُوا۟ مَا طَابَ لَكُم مِّنَ ٱلنِّسَآءِ مَثْنَىٰ وَثُلَٰثَ وَرُبَٰعَ﴾ [النساء: ٣]، ولا يملك إمساك أكثرَ من أربعٍ كما نصّ ابن قدامة في المغني (ج١٠/ص١٤) بحديث «اخْتَرْ مِنْهنَّ أرْبعًا». فإن خاف ألّا يعدل لزمه الاقتصارُ على واحدة: ﴿فَإِنْ خِفْتُمْ أَلَّا تَعْدِلُوا۟ فَوَٰحِدَةً أَوْ مَا مَلَكَتْ أَيْمَٰنُكُمْ ۚ ذَٰلِكَ أَدْنَىٰٓ أَلَّا تَعُولُوا۟﴾ [النساء: ٣]، فالتعليلُ في الآية نفسِها. فهو رخصةٌ مقيَّدةٌ بالعدل لا مطلقة، وليس واجبًا ولا مقصودًا لذاته.'
  WHERE id = 'eac5b364-dc63-4cfd-b2c8-d047ddb49c2a';
UPDATE qa_questions SET answer = 'نعم؛ عذابُ القبر ونعيمُه ثابتان في الصحيحين بنصوصٍ معيَّنةٍ لا بالإجمال، وهما من عقائد أهل السنّة والجماعة. وأصلُ الباب أنّ المبدأ **فتنةُ القبر**، أي سؤالُ الملكين، ثم يتفرّع عنها النعيمُ أو العذاب؛ قال ﷺ: «الْعَبْدُ إِذَا وُضِعَ فِي قَبْرِهِ وَتُوُلِّيَ وَذَهَبَ أَصْحَابُهُ، حَتَّى إِنَّهُ لَيَسْمَعُ قَرْعَ نِعَالِهِمْ، أَتَاهُ مَلَكَانِ فَأَقْعَدَاهُ، فَيَقُولَانِ لَهُ: مَا كُنْتَ تَقُولُ فِي هَذَا الرَّجُلِ مُحَمَّدٍ ﷺ ؟ فَيَقُولُ: أَشْهَدُ أَنَّهُ عَبْدُ اللهِ وَرَسُولُهُ، فَيُقَالُ: انْظُرْ إِلَى مَقْعَدِكَ مِنَ النَّارِ، أَبْدَلَكَ اللهُ بِهِ مَقْعَدًا مِنَ الْجَنَّةِ»، وأمّا الآخرُ «فَيَقُولُ: لَا أَدْرِي، كُنْتُ أَقُولُ مَا يَقُولُ النَّاسُ» (رواه البخاري). وقد نصّ البخاريُّ على أنّ قولَ الله تعالى ﴿يُثَبِّتُ اللهُ الَّذِينَ آمَنُوا بِالْقَوْلِ الثَّابِتِ﴾ [إبراهيم: ٢٧] نزلت في هذا الباب؛ قال البراء بن عازب رضي الله عنهما عن النبيّ ﷺ: «إِذَا أُقْعِدَ الْمُؤْمِنُ فِي قَبْرِهِ أُتِيَ، ثُمَّ شَهِدَ أَنْ لَا إِلَهَ إِلَّا اللهُ، وَأَنَّ مُحَمَّدًا رَسُولُ اللهِ، فَذَلِكَ قَوْلُهُ: ﴿يُثَبِّتُ اللهُ الَّذِينَ آمَنُوا بِالْقَوْلِ الثَّابِتِ﴾ [إبراهيم: ٢٧]»، وفي الرواية الأخرى: «﴿يُثَبِّتُ اللهُ الَّذِينَ آمَنُوا﴾ [إبراهيم: ٢٧] نَزَلَتْ فِي عَذَابِ الْقَبْرِ». **وأسبابُ العذاب منصوصةٌ يُحذَّر منها**، وليس البابُ إجمالًا محضًا؛ قال ابن عباس رضي الله عنهما: «مَرَّ النَّبِيُّ ﷺ بِقَبْرَيْنِ فَقَالَ: إِنَّهُمَا لَيُعَذَّبَانِ، وَمَا يُعَذَّبَانِ فِي كَبِيرٍ، أَمَّا أَحَدُهُمَا فَكَانَ لَا يَسْتَتِرُ مِنَ الْبَوْلِ، وَأَمَّا الْآخَرُ فَكَانَ يَمْشِي بِالنَّمِيمَةِ» (رواه البخاري). وهو ابتلاءٌ عامٌّ لهذه الأمّة، وإنما حُجب سماعُه عنّا رحمةً بنا؛ قال ﷺ: «إن هذه الأمة تبتلى في قبورها. فلولا أن لا تدافنوا، لدعوت لله أن يسمعكم من عذاب القبر الذي أسمع منه» (رواه مسلم). ولأجل ذلك شُرع التعوّذُ منه في الصلاة؛ فكان ﷺ «يَدْعُو فِي الصَّلَاةِ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الْمَحْيَا وَفِتْنَةِ الْمَمَاتِ» (رواه البخاري)، ولم يكن ذلك فعلًا منه فحسب بل **أمرًا لأمّته**؛ قال ﷺ: «إِذَا تَشَهَّدَ أَحَدُكُمْ فَلْيَسْتَعِذْ بِاللَّهِ مِنْ أَرْبَعٍ. يَقُولُ: اللَّهُمَّ! إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ جَهَنَّمَ. وَمِنْ عَذَابِ القبر. ومن فتنة المحيا والممات. ومن شر فتنة المسيح الدجال» (رواه مسلم). وكيفيّةُ ذلك كلِّه غيبٌ يُؤمَن به كما ورد من غير تكييفٍ ولا قياسٍ على أحوال الدنيا، وأمّا أسبابُه وأحكامُه فمنصوصةٌ كما تقدّم.'
  WHERE id = 'f3432fb8-c8f5-4fe9-a025-9af8395128b9';
UPDATE qa_questions SET answer = 'منعُ فعلٍ مباحٍ في أصله لأنه وسيلةٌ تُفضي إلى مفسدةٍ أو محرَّم — وهو عند الشاطبي في الموافقات «راجعٌ إلى طلب ترك ما ثبت طلبُ فعله لعارضٍ يعرض»، و«أصلٌ متفق عليه في الجملة، وإن اختلف العلماء في تفاصيله»؛ فليس مذهبًا خاصًّا بالمالكية والحنابلة، وإنما محلُّ الخلاف تفاصيلُه لا أصلُه. ومن أمثلته المنصوصة قوله تعالى ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَقُولُوا رَاعِنَا﴾ [البقرة: ١٠٤] وقوله ﴿وَلَا تَسُبُّوا الَّذِينَ يَدْعُونَ مِنْ دُونِ اللَّهِ﴾ [الأنعام: ١٠٨]، وكفُّه ﷺ عن قتل المنافقين «لأنه ذريعة إلى قول الكفار: إن محمدًا يقتل أصحابه». والتفصيلُ عند الشاطبي بحسب درجة الإفضاء: فما أداؤه إلى المفسدة نادرٌ «فهو على أصله من الإذن»، وما أداؤه إليها ظنيٌّ فـ«اعتبار الظن هو الأرجح» فيُمنع، وما أداؤه إليها كثيرٌ لا غالبٌ ولا نادرٌ فـ«موضع نظرٍ والتباس»، الأصلُ فيه الإذن «كمذهب الشافعي وغيره»، «إلا أن مالكًا اعتبره في سد الذرائع بناءً على كثرة القصد وقوعًا».'
  WHERE id = 'f8c435b0-e072-4abe-aa12-49198a19b770';
COMMIT;
